import asyncioimport base64import hashlibimport hmacimport jsonimport loggingimport osimport timefrom datetime import datetime, timezonefrom typing import Optionalimport requestsimport websocketsfrom market_data import (    MarketDataStore,    OrderBookStore,    SymbolRanker,    TradeStore,    Signal,)from observation_engine import ObservationWindowManager, ObservationConfigfrom okx_futures_client import OKXFuturesClientfrom execution_engine import DemoFuturesExecutionEngine, ExecutionConfigfrom position_store import PositionHistoryStorefrom cross_exchange_validator import CrossExchangeValidatorfrom movement_tracker import MovementTracker, TradeSnapshotStore, MovementTrackerConfiglogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("okx_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)DEMO_TRADING = True# OKX calls this "Demo Trading" (paper trading), not "testnet". Unlike# BitMart, the WS side uses a completely different host (wspap) for demo# trading rather than a URL flag or query param — see test_ws.py.PROD_PUBLIC_WS = "wss://ws.okx.com:8443/ws/v5/public"PROD_PRIVATE_WS = "wss://ws.okx.com:8443/ws/v5/private"DEMO_PUBLIC_WS = "wss://wspap.okx.com:8443/ws/v5/public"DEMO_PRIVATE_WS = "wss://wspap.okx.com:8443/ws/v5/private"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30# OKX has no single "all tickers" firehose channel like BitMart's# "futures/ticker" — each instId is subscribed individually. The ticker# channel is subscribed for every live USDT-margined swap up front (needed# to rank symbols); depth/trade channels are only subscribed for the# current watchlist, same as before.TICKER_CHANNEL = "tickers"DEPTH_CHANNEL = "books5"  # top-5 snapshot on every push -- simpler than maintaining an incremental bookDEPTH_LEVELS = 5  # books5 only ever gives 5 levels per sideTRADE_CHANNEL = "trades"# OKX subscribe/unsubscribe messages are capped in practical size, so the# full-universe ticker subscription (and any large watchlist diff) is sent# in batches rather than one giant args array.SUBSCRIBE_BATCH_SIZE = 50WATCHLIST_TOP_N = 15WATCHLIST_WARMUP_SEC = 10WATCHLIST_INTERVAL_SEC = 30SYMBOL_STALE_AFTER_SEC = 30TRADE_WINDOWS_MS = (500, 1000, 2000, 5000)POSITION_MONITOR_INTERVAL_SEC = 5.0# --- Demo Futures trade settings ---MARGIN_PER_TRADE_USDT = 5.0REQUESTED_LEVERAGE = 50MIN_LEVERAGE_REQUIRED = 10MAX_OPEN_POSITIONS = 5MAX_TOTAL_TRADES = 20TARGET_NET_PROFIT_USDT = 0.2TARGET_STOP_LOSS_USDT = 0.9OPEN_TYPE = "isolated"# --- Observation Window signal system (see observation_engine.py) ---# This is the ONLY trade-decision logic. It replaces the old# evidence/scoring pipeline (evidence_pipeline.py, event_confirmation.py,# confidence-engine-driven SignalGenerator, signals_histories persistence)# entirely — none of those are imported or called anywhere in this file# anymore.OBSERVATION_TICK_INTERVAL_SEC = 2.0  # how often each observed candidate is re-checkedOBSERVATION_MAX_MINUTES = 20.0  # maximum observation time before a candidate is discarded, NOT a waiting periodTREND_CANDLE_BAR = "5m"TREND_CANDLE_COUNT = 6  # ~30 minutes of 5m candlesTREND_MOVE_THRESHOLD_PCT = 0.003RATIO_WINDOW_SEC = 300  # 5 minutes of executed trades for the buy/sell ratio + net aggressive delta checksMIN_BUY_SELL_RATIO = 0.70  # dominant side must be >= 70% of executed volume (70/30, 80/20, 90/10 all pass; 60/40 doesn't)DELTA_BUCKET_COUNT = 3  # ratio window is split into this many chronological slices; every slice must agree with the trend directionVOLUME_RECENT_WINDOW_SEC = 300VOLUME_BASELINE_WINDOW_SEC = 1800  # 30-minute baseline the recent window's directional volume is compared againstVOLUME_EXPANSION_MULTIPLIER = 1.5MIN_AGREEING_EXCHANGES = 5  # of 7 -- see cross_exchange_validator.py, checking these same four signals per exchangeTOTAL_EXCHANGES = 7# How often to log each observed candidate's current state (trend, ratio,# delta, volume, cross-exchange, elapsed) — the Candidate State visibility# requirement, without spamming a line per symbol per tick.OBSERVATION_LOG_INTERVAL_SEC = 30.0# Symbols the bot should never subscribe to or trade (OKX instId format).BLACKLISTED_SYMBOLS = {"BTC-USDT-SWAP"}# While scanning is paused (position cap or lifetime trade limit reached),# log a single status line at most this often instead of spamming per tick.STATUS_LOG_INTERVAL_SEC = 30.0class WatchlistState:    def __init__(self) -> None:        self.symbols = set()        # Set by run_trading_loop once the position cap is hit, so the        # watchlist/order-flow loops stop churning subscriptions and CPU on        # symbol discovery that won't be acted on anyway — only the position        # monitor keeps running and logging.        self.paused = Falsedef _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_okx_credentials() -> dict:    """Looks for the 'okx' row in the api_keys Supabase table. OKX needs a    passphrase in addition to key/secret (set by you when the key was    created on OKX), so that column has to be populated for this to work.    Mirrors test_ws.py's load_okx_credentials()."""    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "okx"),        None,    )    if not match:        raise RuntimeError("No 'okx' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key_demo"))    api_secret = _clean_secret(match.get("api_secret_demo"))    passphrase = _clean_secret(match.get("passphrase"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("passphrase", passphrase)) if not v]    if missing:        raise RuntimeError(f"OKX credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "passphrase": passphrase}def build_supabase_client():    """Separate client for position_history reads/writes — reuses the same    db.txt config as load_okx_credentials() but keeps that function's    signature (and its callers) unchanged."""    from supabase import create_client    config = _load_db_config()    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_args(api_key: str, api_secret: str, passphrase: str) -> dict:    timestamp = str(int(time.time()))    message = f"{timestamp}GET/users/self/verify"    sign = base64.b64encode(        hmac.new(api_secret.encode(), message.encode(), hashlib.sha256).digest()    ).decode()    return {"apiKey": api_key, "passphrase": passphrase, "timestamp": timestamp, "sign": sign}async def _keepalive(ws):    # OKX's WS ping/pong is plain text ("ping"/"pong"), not a JSON envelope.    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send("ping")        except Exception:            returndef _depth_trade_args(symbols) -> list:    args = []    for s in symbols:        args.append({"channel": DEPTH_CHANNEL, "instId": s})        args.append({"channel": TRADE_CHANNEL, "instId": s})    return argsasync def _send_in_batches(ws, op: str, args: list) -> None:    for i in range(0, len(args), SUBSCRIBE_BATCH_SIZE):        batch = args[i : i + SUBSCRIBE_BATCH_SIZE]        await ws.send(json.dumps({"op": op, "args": batch}))async def _watchlist_loop(ws, ranker: SymbolRanker, order_book: OrderBookStore, trade_store: TradeStore, watchlist_state: WatchlistState):    current = set()    await asyncio.sleep(WATCHLIST_WARMUP_SEC)    while True:        if watchlist_state.paused:            # At the position cap — hold the current subscriptions as-is            # rather than churning them for symbols we won't trade anyway.            await asyncio.sleep(WATCHLIST_INTERVAL_SEC)            continue        top = set(await ranker.top_symbols()) - BLACKLISTED_SYMBOLS        added = top - current        removed = current - top        if removed:            await _send_in_batches(ws, "unsubscribe", _depth_trade_args(removed))            for symbol in removed:                await order_book.remove(symbol)                await trade_store.remove(symbol)        if added:            await _send_in_batches(ws, "subscribe", _depth_trade_args(added))        if added or removed:            current = top            watchlist_state.symbols = set(current)            log.info(f"[watchlist] now tracking {sorted(current)}")        await asyncio.sleep(WATCHLIST_INTERVAL_SEC)def _translate_ticker(row: dict) -> dict:    """OKX 'tickers' channel -> the ticker shape MarketDataStore/SymbolRanker    expect. OKX has no mark-price field on this channel, so mark_price is    approximated with last_price here — fine for signal generation (which    doesn't read mark_price), but monitor_positions() uses the *real*    mark price from get_position() for anything that matters financially."""    pct_change = None    try:        last = float(row.get("last"))        open24h = float(row.get("open24h"))        if open24h:            pct_change = (last - open24h) / open24h    except (TypeError, ValueError):        pass    return {        "symbol": row.get("instId"),        "last_price": row.get("last"),        "mark_price": row.get("last"),        "bid_price": row.get("bidPx"),        "ask_price": row.get("askPx"),        "bid_vol": row.get("bidSz"),        "ask_vol": row.get("askSz"),        "volume_24": row.get("vol24h"),        "range": pct_change if pct_change is not None else 0.0,    }async def _apply_book_snapshot(order_book: OrderBookStore, row: dict) -> None:    """OKX 'books5' pushes a full top-5 snapshot every update (no deltas to    merge), so each side is just replaced wholesale via the existing    apply_depth_update(), same as it already does per-side."""    inst_id = row.get("instId")    if not inst_id:        return    bids = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("bids") or []) if len(lvl) >= 2]    asks = [{"price": lvl[0], "vol": lvl[1]} for lvl in (row.get("asks") or []) if len(lvl) >= 2]    await order_book.apply_depth_update({"symbol": inst_id, "way": 1, "depths": bids})    await order_book.apply_depth_update({"symbol": inst_id, "way": 2, "depths": asks})def _translate_trade(row: dict) -> dict:    return {        "symbol": row.get("instId"),        "price": row.get("px"),        "vol": row.get("sz"),        "side": row.get("side"),  # already "buy"/"sell" -- matches TradeStore's generic side branch        "created_at": row.get("ts"),    }async def run_public(    market_data: MarketDataStore,    order_book: OrderBookStore,    ranker: SymbolRanker,    trade_store: TradeStore,    watchlist_state: WatchlistState,    all_symbols: list,):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                # No "all tickers" firehose on OKX -- subscribe every live                # USDT swap's ticker individually (batched) so the ranker                # has a full universe to score.                ticker_args = [{"channel": TICKER_CHANNEL, "instId": s} for s in all_symbols]                await _send_in_batches(ws, "subscribe", ticker_args)                keepalive_task = asyncio.create_task(_keepalive(ws))                watchlist_task = asyncio.create_task(_watchlist_loop(ws, ranker, order_book, trade_store, watchlist_state))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        event = msg.get("event")                        arg = msg.get("arg") or {}                        channel = arg.get("channel")                        if event == "subscribe":                            continue  # one ack per instId at startup -- too noisy to log each                        elif event == "unsubscribe":                            continue                        elif event == "error":                            log.error(f"[public] \u274c error: {msg}")                        elif channel == TICKER_CHANNEL:                            for row in msg.get("data") or []:                                ticker = _translate_ticker(row)                                await market_data.update_from_ticker(ticker)                                await ranker.update_from_ticker(ticker)                        elif channel == DEPTH_CHANNEL:                            for row in msg.get("data") or []:                                await _apply_book_snapshot(order_book, row)                        elif channel == TRADE_CHANNEL:                            for row in msg.get("data") or []:                                await trade_store.apply_trade(_translate_trade(row))                finally:                    keepalive_task.cancel()                    watchlist_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")THIN_SEPARATOR = "-" * 40def _log_candidate(candidate) -> None:    log.info(THIN_SEPARATOR)    log.info(f"[observation] ACCEPTED {candidate.symbol} — {candidate.status_line()}")    log.info(THIN_SEPARATOR)async def run_trading_loop(    market_data: MarketDataStore,    observation_manager: ObservationWindowManager,    execution_engine: DemoFuturesExecutionEngine,    watchlist_state: WatchlistState,):    """Watchlist -> ObservationWindowManager -> ExecutionEngine.    This is the entire trade-decision path. A symbol becomes a candidate    the moment it enters the watchlist (see ObservationWindowManager.sync_watchlist)    and is observed for up to OBSERVATION_MAX_MINUTES, continuously    re-checked against the four required signals (trend, buy/sell ratio,    net aggressive delta, volume expansion) plus cross-exchange    confirmation of the same four. The trade opens the instant all of    that holds — observation does not wait out the full window once    conditions are met. If the window elapses first, the candidate is    dropped and the watchlist moves on to new candidates.    No confidence scores, whale/event confirmations, or weighted    scoring participate in this decision anywhere — see    observation_engine.py's module docstring for what this replaced.    """    was_blocked = False    last_status_log = 0.0    last_observation_log = 0.0    while True:        await asyncio.sleep(OBSERVATION_TICK_INTERVAL_SEC)        open_count = await execution_engine.open_count()        total_opened = await execution_engine.total_opened()        max_positions = execution_engine.config.max_open_positions        max_total = execution_engine.config.max_total_trades        capacity_block = open_count >= max_positions        total_block = max_total is not None and total_opened >= max_total        blocked = capacity_block or total_block        if blocked and not was_blocked:            reason = (                f"lifetime trade limit reached ({total_opened}/{max_total})"                if total_block                else f"{open_count}/{max_positions} positions open"            )            log.info(                f"[execution] {reason} — pausing signal scans and watchlist subscriptions, "                f"monitoring existing trades only"            )            last_status_log = time.time()        elif was_blocked and not blocked:            log.info(f"[execution] slot freed ({open_count}/{max_positions} open) — resuming signal scans")        was_blocked = blocked        watchlist_state.paused = blocked        if blocked:            now = time.time()            if now - last_status_log >= STATUS_LOG_INTERVAL_SEC:                log.info(                    f"[status] {open_count}/{max_positions} open positions, "                    f"{total_opened}/{max_total} lifetime trades — monitoring only"                )                last_status_log = now            continue        await observation_manager.sync_watchlist(watchlist_state.symbols)        for symbol in list(watchlist_state.symbols):            if symbol in BLACKLISTED_SYMBOLS:                continue            if await execution_engine.is_blacklisted(symbol):                continue            if await execution_engine.open_count() >= execution_engine.config.max_open_positions:                break            if await execution_engine.has_open_position(symbol):                continue            market = await market_data.get(symbol)            if not market:                continue            candidate = await observation_manager.evaluate(symbol)            if candidate is None:                continue            _log_candidate(candidate)            signal = Signal(                symbol=candidate.symbol,                direction=candidate.direction,                confidence=1.0,  # not used for any gating decision -- see execution_engine.py                entry_price=candidate.entry_price,                take_profit=candidate.entry_price,  # unused -- execution_engine computes its own TP from target_net_profit_usdt                stop_loss=candidate.entry_price,  # unused -- execution_engine computes its own SL from target_stop_loss_usdt                timestamp=time.time(),                reasons=[                    f"trend={candidate.trend}",                    f"buy_sell_ratio={candidate.buy_sell_ratio:.2f}",                    f"net_aggressive_delta_ok={candidate.net_aggressive_delta_ok}",                    f"volume_expansion_ok={candidate.volume_expansion_ok}",                    f"cross_exchange_agreeing={candidate.cross_exchange_agreeing}/{observation_manager.config.total_exchanges}",                ],                prerequisites=[],            )            await execution_engine.try_open_trade(signal)        now = time.time()        if now - last_observation_log >= OBSERVATION_LOG_INTERVAL_SEC:            candidates = await observation_manager.snapshot()            if candidates:                for candidate in sorted(candidates, key=lambda c: c.symbol):                    log.info(f"[observation] {candidate.status_line()}")            else:                log.info("[observation] no candidates currently being observed")            last_observation_log = nowasync def run_position_monitor(execution_engine: DemoFuturesExecutionEngine):    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        try:            await execution_engine.monitor_positions()        except Exception:            log.exception("[monitor] error while monitoring open positions")async def run_shutdown_watcher(execution_engine: DemoFuturesExecutionEngine, shutdown_event: asyncio.Event):    """Once the lifetime trade cap has been reached and every trade opened    under it has closed, signal main() to stop the bot so the run can be    reviewed from position_history rather than trading indefinitely."""    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        if await execution_engine.trades_exhausted():            total = await execution_engine.total_opened()            log.info(                f"[shutdown] lifetime trade limit reached ({total}/{execution_engine.config.max_total_trades}) "                f"and all positions are closed — stopping the bot for manual review of position_history"            )            shutdown_event.set()            returnasync def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                login_args = build_login_args(creds["api_key"], creds["api_secret"], creds["passphrase"])                await ws.send(json.dumps({"op": "login", "args": [login_args]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("event") == "login":                            if msg.get("code") == "0":                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on OKX")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif msg.get("event") == "error":                            log.error(f"[private] \u274c error: {msg}")                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_okx_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting OKX Futures bot (demo_trading={DEMO_TRADING})")    okx_client = OKXFuturesClient(        api_key=creds["api_key"],        api_secret=creds["api_secret"],        passphrase=creds["passphrase"],        demo_trading=DEMO_TRADING,    )    instruments = await okx_client.list_swap_instruments()    all_symbols = [i["instId"] for i in instruments if i.get("instId")]    log.info(f"[startup] discovered {len(all_symbols)} live USDT-margined swap instruments")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    ranker = SymbolRanker(top_n=WATCHLIST_TOP_N, stale_after_sec=SYMBOL_STALE_AFTER_SEC)    trade_store = TradeStore(windows_ms=TRADE_WINDOWS_MS)    trade_store.on_unmapped_way = lambda way, payload: log.warning(f"[trade] unmapped way={way!r} — trade skipped: {payload}")    position_store = None    try:        position_store = PositionHistoryStore(build_supabase_client())    except Exception:        log.exception("[position-store] could not initialize — continuing without trade persistence")    movement_tracker = None    try:        movement_tracker = MovementTracker(market_data, TradeSnapshotStore(build_supabase_client()), MovementTrackerConfig())    except Exception:        log.exception("[movement-tracker] could not initialize — continuing without trade movement tracking")    cross_exchange_validator = None    try:        cross_exchange_validator = CrossExchangeValidator()        cross_exchange_validator.start()        await cross_exchange_validator.run_self_test()    except Exception:        log.exception(            "[cross-exchange] could not initialize — continuing WITHOUT cross-exchange "            "confirmation (candidates will need require_cross_exchange=False to ever be "            "accepted, since ObservationConfig defaults to requiring it)"        )        cross_exchange_validator = None    observation_manager = ObservationWindowManager(        trade_store,        market_data,        candle_fetcher=okx_client.get_candles,        cross_exchange_validator=cross_exchange_validator,        config=ObservationConfig(            max_observation_minutes=OBSERVATION_MAX_MINUTES,            trend_candle_bar=TREND_CANDLE_BAR,            trend_candle_count=TREND_CANDLE_COUNT,            trend_move_threshold_pct=TREND_MOVE_THRESHOLD_PCT,            ratio_window_ms=RATIO_WINDOW_SEC * 1000,            min_buy_sell_ratio=MIN_BUY_SELL_RATIO,            delta_bucket_count=DELTA_BUCKET_COUNT,            volume_recent_window_ms=VOLUME_RECENT_WINDOW_SEC * 1000,            volume_baseline_window_ms=VOLUME_BASELINE_WINDOW_SEC * 1000,            volume_expansion_multiplier=VOLUME_EXPANSION_MULTIPLIER,            require_cross_exchange=cross_exchange_validator is not None,            min_agreeing_exchanges=MIN_AGREEING_EXCHANGES,            total_exchanges=TOTAL_EXCHANGES,        ),    )    execution_engine = DemoFuturesExecutionEngine(        okx_client,        ExecutionConfig(            margin_per_trade_usdt=MARGIN_PER_TRADE_USDT,            requested_leverage=REQUESTED_LEVERAGE,            min_leverage_required=MIN_LEVERAGE_REQUIRED,            max_open_positions=MAX_OPEN_POSITIONS,            max_total_trades=MAX_TOTAL_TRADES,            target_net_profit_usdt=TARGET_NET_PROFIT_USDT,            target_stop_loss_usdt=TARGET_STOP_LOSS_USDT,            open_type=OPEN_TYPE,        ),        position_store=position_store,        movement_tracker=movement_tracker,    )    watchlist_state = WatchlistState()    shutdown_event = asyncio.Event()    tasks = [        asyncio.create_task(run_public(market_data, order_book, ranker, trade_store, watchlist_state, all_symbols)),        asyncio.create_task(run_private(creds)),        asyncio.create_task(run_heartbeat(market_data, order_book)),        asyncio.create_task(run_trading_loop(market_data, observation_manager, execution_engine, watchlist_state)),        asyncio.create_task(run_position_monitor(execution_engine)),        asyncio.create_task(run_shutdown_watcher(execution_engine, shutdown_event)),    ]    if movement_tracker is not None:        tasks.append(asyncio.create_task(movement_tracker.run_forever()))    await shutdown_event.wait()    for task in tasks:        task.cancel()    await asyncio.gather(*tasks, return_exceptions=True)    log.info("[shutdown] all background tasks stopped — exiting")if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("okx_futures.py stopped.")